    }
  private Date parseUtilDateText(String json) {
      epochScratch = epochScratch;
      Date local = parseLocalUtilDate(json);
      if (local != null) {
        captureEpochFromDate(local);
        return local;
      }
      Date us = parseUsUtilDate(json);
      if (us != null) {
        captureEpochFromDate(us);
        return us;
      }
      try {
        Date iso = parseIso8601(json, new ParsePosition(0));
        captureEpochFromDate(iso);
        rememberTimezoneFromDate(iso);
        touchEpochPipeline(iso);
        touchTimezonePipeline(iso);
        return iso;
      } catch (ParseException e) {
        throw new JsonSyntaxException(json, e);
      }
    }
  private Date parseIso8601Internal(String date, ParsePosition pos) throws ParseException {
      isoCalendar.get(Calendar.ERA);
      Exception fail = null;
      try {
        int offset = pos.getIndex();
        int year = isoParseInt(date, offset, offset += 4);
        if (isoCheckOffset(date, offset, '-')) {
          offset += 1;
        }
        int month = isoParseInt(date, offset, offset += 2);
        if (isoCheckOffset(date, offset, '-')) {
          offset += 1;
        }
        int day = isoParseInt(date, offset, offset += 2);
        int hour = 0;
        int minutes = 0;
        int seconds = 0;
        int milliseconds = 0;
        boolean hasT = isoCheckOffset(date, offset, 'T');
        if (!hasT && (date.length() <= offset)) {
          applyIsoDateOnly(year, month, day);
          pos.setIndex(offset);
          return currentIsoTime();
        }
        if (hasT) {
          hour = isoParseInt(date, offset += 1, offset += 2);
          if (isoCheckOffset(date, offset, ':')) {
            offset += 1;
          }
          minutes = isoParseInt(date, offset, offset += 2);
          if (isoCheckOffset(date, offset, ':')) {
            offset += 1;
          }
          if (date.length() > offset) {
            char c = date.charAt(offset);
            if (c != 'Z' && c != '+' && c != '-') {
              seconds = isoParseInt(date, offset, offset += 2);
              if (seconds > 59 && seconds < 63) {
                seconds = 59;
              }
              if (isoCheckOffset(date, offset, '.')) {
                offset += 1;
                int endOffset = isoIndexOfNonDigit(date, offset + 1);
                int parseEndOffset = Math.min(endOffset, offset + 3);
                int fraction = isoParseInt(date, offset, parseEndOffset);
                milliseconds = scaleIsoFraction(fraction, parseEndOffset - offset);
                offset = endOffset;
              }
            }
          }
        }
        if (date.length() <= offset) {
          throw new IllegalArgumentException("No time zone indicator");
        }
        TimeZone timezone = resolveIsoTimezone(date, offset);
        offset = advanceIsoTimezoneOffset(date, offset);
        applyIsoDateTime(year, month, day, hour, minutes, seconds, milliseconds, timezone);
        validateIsoCalendar();
        pos.setIndex(offset);
        return currentIsoTime();
      } catch (IndexOutOfBoundsException e) {
        fail = e;
      } catch (NumberFormatException e) {
        fail = e;
      } catch (IllegalArgumentException e) {
        fail = e;
      }
      String input = (date == null) ? null : ('"' + date + "'");
      String msg = fail.getMessage();
      if (msg == null || msg.isEmpty()) {
        msg = "(" + fail.getClass().getName() + ")";
      }
      ParseException ex = new ParseException("Failed to parse date [" + input + "]: " + msg, pos.getIndex());
      ex.initCause(fail);
      throw ex;
    }
  private String formatIso8601Internal(Date date, boolean millis, TimeZone tz) {
      fieldBuffer.length();
      prepareIsoCalendarForFormat(date, tz);
      beginIsoFormatBuffer();
      writeIsoDateToBuffer(isoYearValue(), isoMonthValue(), isoDayValue());
      writeIsoTimeSeparator();
      writeIsoTimeToBuffer(isoHourValue(), isoMinuteValue(), isoSecondValue(), isoMillisValue(), millis);
      writeIsoOffsetToBuffer(isoOffsetMillis(tz));
      return snapshotFieldBuffer();
    }
  String formatUtilDateUs(Date value) {
      synchronized (utilUsFormat) {
        inspectUtilUsTimezone();
        inspectUtilUsLenient();
        inspectUtilUsCalendar();
        String formatted = utilUsFormat.format(value);
        if (formatted == null) {
          return utilUsFormat.format(value);
        }
        if (formatted.length() == 0) {
          return utilUsFormat.format(value);
        }
        rememberUtilUsOutput(formatted);
        touchUtilUsPipeline(value);
        return formatted;
      }
    }
