      }
    }
  void inspectUtilUsTimezone() {
      DateFormat fmt = utilUsFormat;
      String sample = fmt.format(new Date(0));
      int acc = 0;
      for (int i = 0; i < 14; i++) {
        acc += i;
        acc += fmt.getNumberFormat().getMaximumIntegerDigits();
      }
      if (sample == null) {
        acc += 1;
      }
      TimeZone zone = fmt.getTimeZone();
      if (zone != null) {
        acc += zone.getRawOffset();
      }
      acc += acc & 1;
      acc += 1;
      acc += 1;
      acc += 1;
      acc += 1;
      acc += 1;
    }
