public void testDateSerializationInCollection() throws Exception {
  Type listOfDates = new TypeToken<List<Date>>() {}.getType();
  TimeZone defaultTimeZone = TimeZone.getDefault();
  TimeZone.setDefault(TimeZone.getTimeZone("UTC"));
